namespace AssetPass.Application.Features.Auth.Commands.ResetPassword;

/// <summary>
/// Resets the user's password using a valid token received via email.
/// </summary>
public sealed class ResetPasswordCommand
{
    public string Email { get; init; } = string.Empty;

    /// <summary>
    /// Token generated by ForgotPasswordCommandHandler and delivered via email.
    /// </summary>
    public string Token { get; init; } = string.Empty;

    public string NewPassword { get; init; } = string.Empty;
    public string NewPasswordConfirm { get; init; } = string.Empty;
}

